import { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    IconButton,
    Card,
    CardContent,
    Typography,
    TablePagination,
    Box,
    CircularProgress,
    Chip
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import Swal from 'sweetalert2';
import MetaData from '../../Layouts/MetaData';
import { Link } from 'react-router-dom';
import { getAdminBanners, deleteBanner, clearErrors } from '../../../actions/bannerAction';
import { useSnackbar } from 'notistack';
import { DELETE_BANNER_RESET } from '../../../constants/bannerConstants';

const BannersList = () => {
    const dispatch = useDispatch();
    const { enqueueSnackbar } = useSnackbar();

    const { banners, error, loading } = useSelector((state) => state.banners);
    const { error: deleteError, isDeleted } = useSelector((state) => state.banner);

    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(10);

    useEffect(() => {
        if (error) {
            enqueueSnackbar(error, { variant: "error" });
            dispatch(clearErrors());
        }
        if (deleteError) {
            enqueueSnackbar(deleteError, { variant: "error" });
            dispatch(clearErrors());
        }
        if (isDeleted) {
            enqueueSnackbar("Banner Deleted Successfully", { variant: "success" });
            dispatch({ type: DELETE_BANNER_RESET });
        }
        dispatch(getAdminBanners());
    }, [dispatch, error, deleteError, isDeleted, enqueueSnackbar]);

    const handleDelete = (id) => {
        Swal.fire({
            title: "Are you sure?",
            text: "You won't be able to revert this!",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#3085d6",
            cancelButtonColor: "#d33",
            confirmButtonText: "Yes, delete it!",
        }).then((result) => {
            if (result.isConfirmed) {
                dispatch(deleteBanner(id));
            }
        });
    };

    return (
        <Box sx={{ minHeight: '100vh', py: 4 }}>
            <MetaData title="Admin Panel | Manage Banners" />

            <Box sx={{ mb: 6, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box>
                    <div className="flex items-center gap-3 mb-3">
                        <div className="w-10 h-1 bg-green-600 rounded-full"></div>
                        <p className="text-[10px] font-black text-green-900/40 uppercase tracking-[0.3em]">Banners</p>
                    </div>
                    <Typography variant="h4" sx={{ fontWeight: 950, color: '#020617', letterSpacing: '-0.03em', textTransform: 'uppercase' }}>
                        Manage <span style={{ color: '#16a34a' }}>Banners</span>
                    </Typography>
                </Box>
                
                <Link to="/admin/banner/new" className="px-6 py-3 bg-[#16a34a] text-white text-xs font-black uppercase tracking-[0.2em] rounded-xl shadow-lg shadow-green-500/30 hover:scale-105 transition-all no-underline">
                    + Add New Banner
                </Link>
            </Box>

            <Card sx={{
                borderRadius: '35px',
                boxShadow: '0 40px 100px rgba(22, 163, 74, 0.04)',
                border: '1px solid #f1f5f9',
                background: '#ffffff',
                overflow: 'hidden'
            }}>
                <CardContent sx={{ p: 0 }}>
                    <TableContainer sx={{ maxHeight: 'calc(100vh - 350px)' }}>
                        <Table stickyHeader>
                            <TableHead>
                                <TableRow>
                                    {[
                                        { label: 'Image', width: '150px' },
                                        { label: 'Title', width: 'auto' },
                                        { label: 'Status', width: '120px' },
                                        { label: 'Actions', width: '150px' }
                                    ].map((head, i) => (
                                        <TableCell
                                            key={i}
                                            align={i === 0 || i > 1 ? "center" : "left"}
                                            sx={{
                                                fontWeight: 950,
                                                color: 'rgba(2, 6, 23, 0.3)',
                                                fontSize: '10px',
                                                py: 4,
                                                bgcolor: '#f8fafc',
                                                borderBottom: '1px solid #f1f5f9',
                                                textTransform: 'uppercase',
                                                letterSpacing: '0.15em',
                                                width: head.width
                                            }}
                                        >
                                            {head.label}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            </TableHead>

                            <TableBody>
                                {loading ? (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center" sx={{ py: 12 }}>
                                            <CircularProgress size={30} thickness={5} sx={{ color: '#16a34a' }} />
                                            <Typography sx={{ fontWeight: 900, textTransform: 'uppercase', letterSpacing: '0.2em', fontSize: '10px', mt: 3, color: '#16a34a' }}>Loading...</Typography>
                                        </TableCell>
                                    </TableRow>
                                ) : banners?.length > 0 ? (
                                    banners
                                        .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                                        .map((banner) => (
                                            <TableRow
                                                key={banner._id}
                                                sx={{
                                                    transition: 'all 0.4s ease',
                                                    '&:hover': { background: '#f0fdf4' },
                                                    '& td': { borderBottom: '1px solid #f8fafc', py: 3 }
                                                }}
                                            >
                                                <TableCell align="center">
                                                    <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                                                        <img 
                                                            src={`/${banner.image.url}`} 
                                                            alt={banner.title} 
                                                            style={{ width: '120px', height: '60px', objectFit: 'cover', borderRadius: '8px', border: '1px solid #e2e8f0' }} 
                                                        />
                                                    </Box>
                                                </TableCell>
                                                <TableCell align="left">
                                                    <Typography sx={{ fontSize: '13px', color: '#020617', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '-0.01em', mb: 0.5 }}>
                                                        {banner.title}
                                                    </Typography>
                                                    <Typography sx={{ fontSize: '11px', color: '#64748b', fontWeight: 500 }}>
                                                        {banner.subtitle.substring(0, 60)}...
                                                    </Typography>
                                                </TableCell>
                                                <TableCell align="center">
                                                    <Chip 
                                                        label={banner.isActive ? 'Active' : 'Inactive'} 
                                                        size="small"
                                                        sx={{ 
                                                            fontSize: '9px', 
                                                            fontWeight: 900, 
                                                            textTransform: 'uppercase', 
                                                            letterSpacing: '0.1em',
                                                            bgcolor: banner.isActive ? '#dcfce7' : '#fee2e2',
                                                            color: banner.isActive ? '#16a34a' : '#ef4444'
                                                        }} 
                                                    />
                                                </TableCell>
                                                <TableCell align="center">
                                                    <Box sx={{ display: 'flex', justifyContent: 'center', gap: 1.5 }}>
                                                            <Link to={`/admin/banner/${banner._id}`}>
                                                                <IconButton
                                                                    sx={{
                                                                        color: '#3b82f6',
                                                                        background: '#eff6ff',
                                                                        borderRadius: '12px',
                                                                        '&:hover': { background: '#3b82f6', color: '#fff' },
                                                                        transition: 'all 0.3s ease'
                                                                    }}
                                                                >
                                                                    <EditIcon sx={{ fontSize: 18 }} />
                                                                </IconButton>
                                                            </Link>
                                                            <IconButton
                                                                onClick={() => handleDelete(banner._id)}
                                                                sx={{
                                                                    color: '#ef4444',
                                                                    background: '#fef2f2',
                                                                    borderRadius: '12px',
                                                                    '&:hover': { background: '#ef4444', color: '#fff' },
                                                                    transition: 'all 0.3s ease'
                                                                }}
                                                            >
                                                                <DeleteIcon sx={{ fontSize: 18 }} />
                                                            </IconButton>
                                                    </Box>
                                                </TableCell>
                                            </TableRow>
                                        ))
                                ) : (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center" sx={{ py: 12 }}>
                                            <Typography sx={{ fontWeight: 900, textTransform: 'uppercase', letterSpacing: '0.2em', fontSize: '11px', opacity: 0.2 }}>No Banners Found</Typography>
                                        </TableCell>
                                    </TableRow>
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    <TablePagination
                        component="div"
                        count={banners?.length || 0}
                        page={page}
                        onPageChange={(e, newPage) => setPage(newPage)}
                        rowsPerPage={rowsPerPage}
                        onRowsPerPageChange={(e) => {
                            setRowsPerPage(parseInt(e.target.value, 10));
                            setPage(0);
                        }}
                        rowsPerPageOptions={[10, 25, 50]}
                        sx={{
                            borderTop: '1px solid #f1f5f9',
                            px: 4,
                            '& .MuiTablePagination-selectLabel, & .MuiTablePagination-displayedRows': {
                                fontWeight: 900,
                                textTransform: 'uppercase',
                                fontSize: '10px',
                                color: 'rgba(2, 6, 23, 0.3)',
                                letterSpacing: '0.1em'
                            }
                        }}
                    />
                </CardContent>
            </Card>
        </Box>
    );
};

export default BannersList;
